import {
  Mesh,
  PlaneGeometry,
  Group,
  DoubleSide,
  Texture,
  Object3D,
} from 'three/webgpu';
import {
  MeshBasicNodeMaterial,
  texture,
  uv,
  mix,
} from 'three/tsl';
import { gsap } from 'gsap';
import '@/primitives';
import '@/text';

/**
 * @typedef {object} NodeConfig
 * @property {{imageUrl:string}} assets
 * @property {{position:[number,number,number],rotation:[number,number,number],scale:[number,number,number]}} scenePlacement
 * @property {string} textContent
 * @property {any[]} cinematicPrimitives
 * @property {any} [neighbors]
 *
 * @typedef {object} NodeContext
 * @property {{ textureLoader: { load: (url:string)=>Texture } }} textureLoader
 * @property {{ fontAtlas: any }} fontAtlas
 * @property {{ primitives: Record<string, Function> }} primitives
 */

/**
 * Creates a textured plane node with optional MSDF text.
 *
 * @param {NodeConfig} config
 * @param {NodeContext} ctx
 * @returns {THREE.Object3D}
 */
export default function createNode(config, ctx) {
  // ---------- Texture ----------
  const tex = ctx.textureLoader.load(config.assets.imageUrl);

  // ---------- Geometry ----------
  const geometry = new PlaneGeometry(1, 1, 1, 1);
  // Preserve aspect ratio of source image
  const imgAspect = 512 / 320; // fallback if unknown
  geometry.scale(imgAspect, 1, 1);

  // ---------- Material (Node) ----------
  const material = new MeshBasicNodeMaterial({
    side: DoubleSide,
    transparent: true,
  });
  // mapNode expects a Node that yields a vec4 color; use texture node
  material.mapNode = texture(tex);
  // Ensure we sample correctly
  material.alphaNode = texture(tex).a;

  // ---------- Mesh ----------
  const plane = new Mesh(geometry, material);
  const [px, py, pz] = config.scenePlacement.position ?? [0, 0, 0];
  const [rx, ry, rz] = config.scenePlacement.rotation ?? [0, 0, 0];
  const [sx, sy, sz] = config.scenePlacement.scale ?? [1, 1, 1];
  plane.position.set(px, py, pz);
  plane.rotation.set(rx, ry, rz);
  plane.scale.set(sx, sy, sz);
  plane.name = 'hero-headline-plane';

  // ---------- Text (MSDF) ----------
  /** @type {THREE.Object3D|null} */
  let textObj = null;
  if (config.textContent && ctx.fontAtlas) {
    // The fontAtlas API is expected to provide a method to create a text mesh.
    // We guard against missing implementation.
    if (typeof ctx.fontAtlas.createTextMesh === 'function') {
      textObj = ctx.fontAtlas.createTextMesh(config.textContent, {
        font: 'display',
        // Approximate size: use design token body scale (0.13 scene units)
        size: 0.13,
        color: '#16161d',
        // Align centered beneath the image plane
        anchor: 'center',
      });
      // Position text slightly in front of the plane to avoid Z‑fight
      textObj.position.set(0, -0.6, 0.001);
    }
  }

  // ---------- Root Group ----------
  const root = new Group();
  root.add(plane);
  if (textObj) root.add(textObj);
  root.name = 'hero-headline-node';

  // ---------- Cinematic Primitives ----------
  if (Array.isArray(config.cinematicPrimitives)) {
    config.cinematicPrimitives.forEach((primitive) => {
      const fn = ctx.primitives[primitive.name];
      if (typeof fn === 'function') {
        fn(root, primitive.params);
      }
    });
  }

  // ---------- Handlers ----------
  root.userData.handlers = {};

  // ---------- Cleanup ----------
  const timelines = [];
  root.userData.cleanup = () => {
    // Dispose geometries and materials
    geometry.dispose();
    material.dispose();
    tex.dispose();

    // Dispose text resources if any
    if (textObj && typeof textObj.traverse === 'function') {
      textObj.traverse((obj) => {
        if (obj.isMesh) {
          if (obj.geometry) obj.geometry.dispose();
          if (obj.material) {
            if (Array.isArray(obj.material)) {
              obj.material.forEach((m) => m.dispose());
            } else {
              obj.material.dispose();
            }
          }
        }
      });
    }

    // Kill GSAP timelines
    timelines.forEach((tl) => tl.kill());

    // Remove from parent if attached
    if (root.parent) root.parent.remove(root);
  };

  return root;
}
